import{Lt as e,Vt as t,Z as n,_t as r,bt as i,vt as a}from"./chunks/framework.CsLlEPF4.js";var o=JSON.parse(`{"title":"术语对照表","description":"","frontmatter":{"title":"术语对照表"},"headers":[],"relativePath":"csl-dev-guide/glossary.md","filePath":"wiki/csl-dev-guide/glossary.md"}`),s={name:`csl-dev-guide/glossary.md`};function c(n,o,s,c,l,u){let d=t(`NolebaseGitContributors`),f=t(`NolebaseGitChangelog`);return e(),r(`div`,null,[o[0]||=a(`<div style="display:none;" hidden data-nosnippet>Are you an LLM? You can read better optimized documentation at /csl-dev-guideglossary.md for this page in Markdown format</div><h1 id="术语对照表" tabindex="-1">术语对照表 <a class="header-anchor" href="#术语对照表" aria-label="Permalink to “术语对照表”">​</a></h1><p>以下按照在文中出现的顺序罗列了本文翻译时对某些术语采取的译法，并给出其基本解释，便于读者对照理解。这些术语可能比较少见，或在本文中有特定的含义，其他涉及技术背景的术语已经在正文中给出解释，此处不再赘述。</p><h2 id="引注-citation" tabindex="-1">引注（citation） <a class="header-anchor" href="#引注-citation" aria-label="Permalink to “引注（citation）”">​</a></h2><p>在正文中标注「此处有参考文献」的标志，在不同的引用风格中表现为不同的文本，可能是引用的次序或被引用文献相关信息组成的简短文本。</p><h2 id="参考文献表-bibliography" tabindex="-1">参考文献表（bibliography） <a class="header-anchor" href="#参考文献表-bibliography" aria-label="Permalink to “参考文献表（bibliography）”">​</a></h2><p>国标中称为「参考文献表」，亦有部分文献称之为「书目」，是集中展示被引文献详情的列表，可能位于章节末尾、全文末尾、每一页的页脚。</p><h2 id="引用格式-citation-format" tabindex="-1">引用格式（citation format） <a class="header-anchor" href="#引用格式-citation-format" aria-label="Permalink to “引用格式（citation format）”">​</a></h2><p>对于「如何在文章中标示参考文献」的规范标准，特指一整个标准体系，如 GB/T 7714-2015，而不是诸如是「作者名需要大写」这样的具体规定。</p><h2 id="条目-item" tabindex="-1">条目（item） <a class="header-anchor" href="#条目-item" aria-label="Permalink to “条目（item）”">​</a></h2><p>即 Zotero 中的「条目」，指对文献的相关信息的记录，条目中通常含有那些用于分类、引用的信息，并非指文献的内容本身。</p><h2 id="参考文献条目-bibliographic-entry" tabindex="-1">参考文献条目（bibliographic entry） <a class="header-anchor" href="#参考文献条目-bibliographic-entry" aria-label="Permalink to “参考文献条目（bibliographic entry）”">​</a></h2><p>参考文献表的组成单位，即参考文献表中的项目，除了 <code>numeric</code> 复合风格之外，一个参考文献条目往往对应一篇被引用的文献。</p><h2 id="风格-style" tabindex="-1">风格（style） <a class="header-anchor" href="#风格-style" aria-label="Permalink to “风格（style）”">​</a></h2><p>对一些相似的引用格式的统称，如 <code>in-text</code> 风格、<code>note</code> 风格等。</p><h2 id="样式-style" tabindex="-1">样式（style） <a class="header-anchor" href="#样式-style" aria-label="Permalink to “样式（style）”">​</a></h2><p>特指 <code>CSL</code> 的 style 文件及其代码，是对引用格式的代码实现。注意区别于 Microsoft Word 中的「样式」，在 Microsoft Word 中，「样式」是指若干具体格式的集合。</p><h2 id="本地化文件-locale-file" tabindex="-1">本地化文件（locale file） <a class="header-anchor" href="#本地化文件-locale-file" aria-label="Permalink to “本地化文件（locale file）”">​</a></h2><p>CSL 预置的一些文件，它用来将日期或<a href="#术语term">术语</a>翻译为特定语言区域所采用的形式。</p><h2 id="术语-term" tabindex="-1">术语（term） <a class="header-anchor" href="#术语-term" aria-label="Permalink to “术语（term）”">​</a></h2><p>在 <code>locale file</code> 有关的语境里，「术语」指那些出现在引文或参考文献条目中用于串起相关信息的固定短语，如「xx<strong>等</strong>」、「xx<strong>编</strong>」、「<strong>载于</strong>xx」中的术语就分别连接着著者、编者、出版物来源的信息。</p><h2 id="翻译-translation" tabindex="-1">翻译（translation） <a class="header-anchor" href="#翻译-translation" aria-label="Permalink to “翻译（translation）”">​</a></h2><p>在 <code>locale file</code> 有关的语境里，「翻译」特指术语（term）在不同语言中的翻译。</p><h2 id="形式-form" tabindex="-1">形式（form） <a class="header-anchor" href="#形式-form" aria-label="Permalink to “形式（form）”">​</a></h2><p>指词形，即词语在不同的语境中使用的不同形态。如名词的单复数形式、词语的动词/名词形式等、数量词数量形式和序数形式。</p><h2 id="日期成分-date-part" tabindex="-1">日期成分（date-part） <a class="header-anchor" href="#日期成分-date-part" aria-label="Permalink to “日期成分（date-part）”">​</a></h2><p>即日期的组成成分，包括年、月、日。</p><h2 id="姓名成分-name-part" tabindex="-1">姓名成分（name-part） <a class="header-anchor" href="#姓名成分-name-part" aria-label="Permalink to “姓名成分（name-part）”">​</a></h2><p>即姓名的组成成分，包括姓、名、不可省略小品词、可省略小品词、后缀。</p><h2 id="名称-name" tabindex="-1">名称（name） <a class="header-anchor" href="#名称-name" aria-label="Permalink to “名称（name）”">​</a></h2><p>泛指人名和机构名。</p><h2 id="姓名-name" tabindex="-1">姓名（name） <a class="header-anchor" href="#姓名-name" aria-label="Permalink to “姓名（name）”">​</a></h2><p>在强调姓名组成成分的语境中，「name」直接翻译为「姓名」。</p><h2 id="名字-name" tabindex="-1">名字（name） <a class="header-anchor" href="#名字-name" aria-label="Permalink to “名字（name）”">​</a></h2><p>「名字」是「姓名」的同义词，特指人的名称，但不强调其组成成分。</p><h2 id="人名-personal-name" tabindex="-1">人名（personal name） <a class="header-anchor" href="#人名-personal-name" aria-label="Permalink to “人名（personal name）”">​</a></h2><p>即指代个人的名称，含有姓名成分。</p><h2 id="书写系统-script" tabindex="-1">书写系统（script） <a class="header-anchor" href="#书写系统-script" aria-label="Permalink to “书写系统（script）”">​</a></h2><p>指书面文字的体系，如中文、拉丁文、西里尔文等。</p><h2 id="替补-substitute" tabindex="-1">替补（substitute） <a class="header-anchor" href="#替补-substitute" aria-label="Permalink to “替补（substitute）”">​</a></h2><p>在 <code>cs:names</code> 元素中，当首选的名称变量不存在时，可接替其位置渲染其他内容的子句。</p><h2 id="定位词-locator" tabindex="-1">定位词（locator） <a class="header-anchor" href="#定位词-locator" aria-label="Permalink to “定位词（locator）”">​</a></h2>`,42),i(d),i(f)])}var l=n(s,[[`render`,c]]);export{o as __pageData,l as default};